  'EBSIOBalance% — 0 근접 시 인스턴스 EBS baseline으로 강등 (볼륨이 커도 병목)': { en: 'EBSIOBalance% — near 0 drops the instance to its EBS baseline (a bottleneck even with large volumes)', zh: 'EBSIOBalance% — 接近 0 时实例降级到 EBS 基线（卷再大也会成为瓶颈）', ja: 'EBSIOBalance% — 0 に近づくとインスタンスが EBS baseline に降格（ボリュームが大きくてもボトルネック）' },
  '인스턴스 EBS 대역폭 밸런스': { en: 'Instance EBS bandwidth balance', zh: '实例 EBS 带宽余额', ja: 'インスタンス EBS 帯域幅バランス' },
  '메모리 설정이 곧 성능 — 상향 시 CPU/네트워크도 비례 증가 (가이드 참조)': { en: 'Memory setting is performance — raising it scales CPU/network proportionally (see guide)', zh: '内存配置即性能 — 调高时 CPU/网络也按比例增加（参见指南）', ja: 'メモリ設定がそのまま性能 — 上げると CPU/ネットワークも比例して増加（ガイド参照）' },
  'Invocations — 선택 기간 누적, 트래픽 기준선': { en: 'Invocations — cumulative over the selected range, traffic baseline', zh: 'Invocations — 所选时间段累计，流量基线', ja: 'Invocations — 選択期間累計、トラフィックの基準線' },
  'Errors — 선택 기간 누적 (핸들러 예외·타임아웃)': { en: 'Errors — cumulative over the selected range (handler exceptions and timeouts)', zh: 'Errors — 所选时间段累计（处理程序异常·超时）', ja: 'Errors — 選択期間累計（ハンドラ例外・タイムアウト）' },
  '에러율': { en: 'Error rate', zh: '错误率', ja: 'エラー率' },
