  'DiskQueueDepth — 높으면 스토리지 병목': { en: 'DiskQueueDepth — high values indicate a storage bottleneck', zh: 'DiskQueueDepth — 偏高表示存储瓶颈', ja: 'DiskQueueDepth — 高いとストレージボトルネック' },
