  'OperationsFailedReplication — >0이면 권한/설정 문제 조사': { en: 'OperationsFailedReplication — if >0, investigate permission/configuration issues', zh: 'OperationsFailedReplication — 若 >0，请排查权限/配置问题', ja: 'OperationsFailedReplication — >0 なら権限/設定の問題を調査' },
  '복제 상태 (CRR/SRR, 선택 기간)': { en: 'Replication Status (CRR/SRR, selected range)', zh: '复制状态（CRR/SRR，所选时间范围）', ja: 'レプリケーション状況（CRR/SRR、選択期間）' },
