  '5xx(선택 기간 누적) — 급증 시 서버 측 이상': { en: '5xx (cumulative over the selected period) — a spike indicates a server-side problem', zh: '5xx（所选时间段累计）— 激增表示服务器端异常', ja: '5xx（選択期間累計）— 急増はサーバー側の異常' },
  'AutomatedSnapshotFailure — 값 1 = 자동 스냅샷(백업) 실패': { en: 'AutomatedSnapshotFailure — value 1 = automated snapshot (backup) failed', zh: 'AutomatedSnapshotFailure — 值为 1 = 自动快照（备份）失败', ja: 'AutomatedSnapshotFailure — 値 1 = 自動スナップショット（バックアップ）失敗' },
